with base as (select id, customer_id, store_id, order_date, channel, amount, discount, shipping_fee, datediff(current_date(), order_date) as days_since_order_date from orders where order_date > date '2023-06-14'), valid as (select *, date_trunc('month', order_date) as order_date_period from base where channel not in ('store', 'partner')), not_flagged as (select s.* from valid s where not exists (select 1 from order_items c where c.order_id = s.id and c.unit_price < 220)), latest_match as (select s.*, x.payment_amount, x.payment_status from not_flagged s join lateral (select c.amount as payment_amount, c.status as payment_status from payments c where c.order_id = s.id order by c.amount desc, c.id desc limit 1) x on true), with_window as (select e.*, pr.id as promo_id, pr.promo_code, pr.discount_pct from latest_match e left join promotions pr on coalesce(e.channel, 'store') = pr.channel and e.order_date >= pr.starts_on and e.order_date <= date_add(pr.ends_on, 10)), metrics as (select *, row_number() over (partition by promo_code, channel order by order_date, id, promo_id) as row_seq, lead(discount_pct, 2) over (partition by store_id order by discount, id, promo_id) as next_discount_pct from with_window), attributed as (select a.*, sub.id as subscription_id, sub.plan, sub.monthly_fee from metrics a left join subscriptions sub on a.customer_id = sub.customer_id and a.order_date_period >= sub.start_date and a.order_date_period < sub.end_date + interval 7 days) select case when discount_pct >= 0.34 then 'PREMIUM' else 'STANDARD' end as discount_pct_tier, case when subscription_id >= 10 then 'LARGE' else 'SMALL' end as subscription_id_tier, channel, percentile_approx(row_seq, 0.95) as row_seq_p95, size(collect_set(promo_code)) as num_promo_codes, count(case when plan = 'basic' then 1 end) as basic_count from attributed group by grouping sets ((case when discount_pct >= 0.34 then 'PREMIUM' else 'STANDARD' end, case when subscription_id >= 10 then 'LARGE' else 'SMALL' end, channel), (case when discount_pct >= 0.34 then 'PREMIUM' else 'STANDARD' end, case when subscription_id >= 10 then 'LARGE' else 'SMALL' end), (case when discount_pct >= 0.34 then 'PREMIUM' else 'STANDARD' end), ());
